        }

        for (double d: someDoubles(0, 2.0e-5)) {
            assertThat("digamma of " + d,
                       Scalars.digamma(d),
                       closeTo(Gamma.digamma(d), 1.0e-8));
        }

        for (double d: someDoubles(-10, 0)) {
            assertThat("digamma of " + d,
                       Scalars.digamma(d),
                       closeTo(Gamma.digamma(d), 1.0e-8));
        }

        for (double d: someDoubles(0, 10)) {
            assertThat("digamma of " + d,
                       Scalars.digamma(d),
                       closeTo(Gamma.digamma(d), 1.0e-8));
        }
    }

Function:
public class CalculateRequests {
static int calculateRequests(int cpuLoad, int limit, int maxRequests) {

        // Validations
        if (cpuLoad < limit) {
            return maxRequests;
        }
        if (limit == 100) {
            // do not throttle in this case
            return maxRequests;
        }

        double fillLevel = (100.0 - cpuLoad) / (100.0 - limit);
        return (int) Math.round(fillLevel * maxRequests);

    }
}

