        assertEquals(EXPECTED_1_5_POWER, MathUtil.powRetainingSign(2, 1.5));
        assertEquals(-EXPECTED_1_5_POWER, MathUtil.powRetainingSign(-2, 1.5));
    }

Function:
public class IsHexit {
public static boolean isHexit(char ch)
        {
        // hexits in the unicode range appear in this order:
        //   {..., 0, ..., 9, ..., A, ..., F, ..., a, ..., f, ...}
        // so a hexit has to be in the range 0..f, and the entire character
        // range from 0..f is only 0x36 (so it fits inside a long mask)
        return ch >= '0' & ch <= 'f' & ((1L << ('f' - ch)) &
                // 3               4               5               6
                // 0123456789ABCDEF0123456789ABCDEF0123456789ABCDEF0123456
                // 0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[/]^_`abcdef
                0b01111111111000000011111100000000000000000000000000111111L) != 0;
        }
}

Test Case:
@Test
    public void testIsHexit()
        {
        Assert.assertTrue(isHexit('0'));
        Assert.assertTrue(isHexit('1'));
        Assert.assertTrue(isHexit('2'));
        Assert.assertTrue(isHexit('3'));
        Assert.assertTrue(isHexit('4'));
        Assert.assertTrue(isHexit('5'));
        Assert.assertTrue(isHexit('6'));
        Assert.assertTrue(isHexit('7'));
        Assert.assertTrue(isHexit('8'));
        Assert.assertTrue(isHexit('9'));
        Assert.assertTrue(isHexit('A'));
        Assert.assertTrue(isHexit('B'));
        Assert.assertTrue(isHexit('C'));
        Assert.assertTrue(isHexit('D'));
        Assert.assertTrue(isHexit('E'));
        Assert.assertTrue(isHexit('F'));
        Assert.assertTrue(isHexit('a'));
        Assert.assertTrue(isHexit('b'));
        Assert.assertTrue(isHexit('c'));
        Assert.assertTrue(isHexit('d'));
        Assert.assertTrue(isHexit('e'));
        Assert.assertTrue(isHexit('f'));
        Assert.assertFalse(isHexit('.'));
        Assert.assertFalse(isHexit('/'));
        Assert.assertFalse(isHexit(':'));
        Assert.assertFalse(isHexit(';'));
        Assert.assertFalse(isHexit((char) 0));
        Assert.assertFalse(isHexit(' '));
        Assert.assertFalse(isHexit('~'));
        Assert.assertFalse(isHexit('@'));
        Assert.assertFalse(isHexit('`'));
        Assert.assertFalse(isHexit('G'));
        Assert.assertFalse(isHexit('g'));
        }

Function:
public class ConvertHalfToFloat {
public static float convertHalfToFloat(short half) {
        switch ((int) half) {
            case 0x0000:
                return 0f;
            case 0x8000:
                return -0f;
            case 0x7c00:
                return Float.POSITIVE_INFINITY;
            case 0xfc00:
                return Float.NEGATIVE_INFINITY;
            // TODO: Support for NaN?
            default:
                return Float.intBitsToFloat(((half & 0x8000) << 16)
                        | (((half & 0x7c00) + 0x1C000) << 13)
                        | ((half & 0x03FF) << 13));
        }
    }
}

