        assertTrue(isClockwise(a, b, c));
        assertTrue(isClockwise(b, c, a));
        assertTrue(isClockwise(c, a, b));
        assertFalse(isClockwise(c, b, a));
        assertFalse(isClockwise(a, c, b));
        assertFalse(isClockwise(b, a, c));
    }

Function:
public class ConvertQNToDouble {
protected double convertQNToDouble(int q, int n) {

        // convert it to a double
        double qDouble = (double) q;

        // get the sign bit
        int signBit = (q >> 15) & 0x1;
        int sign = 0;
        if (signBit == 0) {
            sign = 1;
        }
        else {
            sign = -1;
        }

        // multiply it by 2^(-n)
        return sign * qDouble * Math.pow(2, -1 * n);

    }
}

