Function:
public class CountBits {
static int[] countBits(int num) {
        if (num < 0) return null;

        int[] result = new int[num + 1];
        String binary;
        int count;
        //[0, 1, 10, 11, 100, 101]
        for (int i = 0; i <= num; i++) {
            binary = Integer.toBinaryString(i);
            count = 0;
            for (char c : binary.toCharArray()) {
                if (c == '1')
                    count++;
            }
            result[i] = count;
        }
        return result;
    }
}

