		assertEquals("round 0.5", 1L, MathUtil.round(0.5));
		assertEquals("round -0.5", -1L, MathUtil.round(-0.5));
		assertEquals("round 50.5", 51L, MathUtil.round(50.5));
		assertEquals("round -50.5", -51L, MathUtil.round(-50.5));
		assertEquals("round +Infinity", Long.MAX_VALUE, MathUtil.round(Double.POSITIVE_INFINITY));
		assertEquals("round -Infinity", Long.MIN_VALUE, MathUtil.round(Double.NEGATIVE_INFINITY));
		assertEquals("round NaN", 0L, MathUtil.round(Double.NaN));
	}

Function:
public class GetAlphaAdjoint {
protected double[] getAlphaAdjoint(double k, double x, double beta) {

    double w1 = Math.pow(x, -beta);
    double w2 = x - k;
    double w3 = w2 * w1;

    double w2Bar = w1;
    double w1Bar = w2;

    double[] res = new double[4];
    res[0] = w3;
    res[1] = -w2Bar; // kBar
    res[2] = w2Bar - beta * w1 / x * w1Bar; // xBar
    res[3] = -Math.log(x) * w3; // betaBar

    return res;
  }
}

Test Case:
@Test
  public void alphaTest() {
    final double k = 123;
    final double x = 204;
    final double beta = 2.3;

    final BjerksundStenslandModel bs = new BjerksundStenslandModel();

    final double[] sense = bs.getAlphaAdjoint(k, x, beta);
    final double[] parms = new double[] {k, x, beta };
    final int n = parms.length;
    final double eps = 1e-5;
    for (int i = 0; i < n; i++) {
      final double[] temp = Arrays.copyOf(parms, n);
      temp[i] += eps;
      final double up = bs.getAlphaAdjoint(temp[0], temp[1], temp[2])[0];
      temp[i] -= 2 * eps;
      final double down = bs.getAlphaAdjoint(temp[0], temp[1], temp[2])[0];
      final double fd = (up - down) / 2 / eps;
      assertEquals(fd, sense[i + 1], Math.abs(fd) * 1e-8);
    }
  }

Function:
public class GetKappaAdjoint {
protected double[] getKappaAdjoint(double gamma, double b, double sigmaSq) {
    double[] res = new double[4];
    double temp = 2 * b / sigmaSq;
    res[0] = temp + 2 * gamma - 1;
    res[1] = 2.0; // gammaBar
    res[2] = 2 / sigmaSq; // bBar
    res[3] = -temp / sigmaSq; // sigmasqBar
    return res;
  }
}

