Test Case:
@Test
    public void threadSleepTest() {
        // GIVEN
        final long testStart = System.currentTimeMillis();
        final long requestedSleepDuration = 85L;
        final long measuringMargin = 100L;

        // WHEN
        WearUtil.threadSleep(requestedSleepDuration);
        final long measuredSleepDuration = System.currentTimeMillis() - testStart;

        // THEN
        // we cannot guarantee to be exact to the millisecond - we add some margin of error
        assertThat(measuredSleepDuration, is(both(greaterThan(60L)).and(lessThan(requestedSleepDuration+measuringMargin))));
    }

Function:
public class FromIndex {
int fromIndex(int page, int perPage, int totalEntries) {
        // invalid parameters
        if (page <= 0 || perPage <= 0 || totalEntries < 0) {
            return 0;
        }
        // impossible pages
        if ((page - 1) * perPage >= totalEntries) {
            return 0;
        }
        // valid and possible pages
        return (page - 1) * perPage;
    }
}

Test Case:
@Test
    public void testFromIndex() throws Exception {
        PaginationHelper paginationHelper = new PaginationHelper<>(null, null);
        // invalid: just return 0
        // parameters
        assertEquals(0, paginationHelper.fromIndex(0, 1, 2));
        assertEquals(0, paginationHelper.fromIndex(1, 0, 2));
        assertEquals(0, paginationHelper.fromIndex(-1, 1, 2));
        assertEquals(0, paginationHelper.fromIndex(1, -1, 2));
        assertEquals(0, paginationHelper.fromIndex(1, 1, -1));
        // impossible pages
        assertEquals(0, paginationHelper.fromIndex(20, 10, 5));
        assertEquals(0, paginationHelper.fromIndex(2, 10, 10));
        assertEquals(0, paginationHelper.fromIndex(2, 100, 100));

        // valid
        assertEquals(0, paginationHelper.fromIndex(1, 10, 2));
        assertEquals(10, paginationHelper.fromIndex(2, 10, 11));
        assertEquals(264, paginationHelper.fromIndex(23, 12, 1230));
    }

Function:
public class ToIndex {
int toIndex(int page, int perPage, int totalEntries) {
        // invalid parameters
        if (page <= 0 || perPage <= 0 || totalEntries < 0) {
            return 0;
        }
        // behind the limited range
        if ((page - 1) * perPage >= totalEntries) {
            return 0;
        }
        // valid and possible pages
        return perPage * page < totalEntries ? perPage * page : totalEntries;
    }
}

