Function:
public class NextLexicographicElement {
public static boolean nextLexicographicElement(int x[], int c[]) {
		assert(x.length == c.length);
		final int l = x.length;
		if (l < 1) {
			return false;
		}

		// iterate over the elements starting at the end, until we find an element that can be incremented.
		for (int i = l - 1; i >= 0; --i) {
			++x[i];
			if (x[i] == c[i]) {
				x[i] = 0;
			} else {
				return true; // greater permutation found
			}
		}
		return false; // no greater permutation found (and array reset to {0, ...})
	}
}

Test Case:
@Test
	public void testNextLexicographicElement() {
		int c[] = new int[] {1, 2, 3, 1};
		int x[] = new int[] {0, 0, 0, 0};

		assertTrue(CollectionUtil.nextLexicographicElement(x, c));
		assertArrayEquals(new int[] {0, 0, 1, 0}, x);
		assertTrue(CollectionUtil.nextLexicographicElement(x, c));
		assertArrayEquals(new int[] {0, 0, 2, 0}, x);
		assertTrue(CollectionUtil.nextLexicographicElement(x, c));
		assertArrayEquals(new int[] {0, 1, 0, 0}, x);
		assertTrue(CollectionUtil.nextLexicographicElement(x, c));
		assertArrayEquals(new int[] {0, 1, 1, 0}, x);
		assertTrue(CollectionUtil.nextLexicographicElement(x, c));
		assertArrayEquals(new int[] {0, 1, 2, 0}, x);
		assertFalse(CollectionUtil.nextLexicographicElement(x, c));
		assertArrayEquals(new int[] {0, 0, 0, 0}, x);

		assertFalse(CollectionUtil.nextLexicographicElement(new int[] { 0 }, new int[] { 1 }));
		assertTrue(CollectionUtil.nextLexicographicElement(new int[] { 0 }, new int[] { 2 }));
	}

Function:
public class Format {
public static String format(long numericalValue) {
        // Based on http://programming.guide/java/formatting-byte-size-to-human-readable-format.html
        if (numericalValue < 1024) {
            return numericalValue + " B";
        }
        int exp = (int) (Math.log(numericalValue) / Math.log(1024));
        String pre = "KMGTPE".charAt(exp - 1) + "i";
        return String.format("%.0f %sB", numericalValue / Math.pow(1024, exp), pre);
    }
}

